use semio_framework_value_paged_list::{PagedList,PagedListReservationOutcome,PagedListReservationFailure,PagedListReleaseOutcome};
use semio_framework_value_control_contract::{RetainedCloneProgress,RetainedWorkPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread};
#[test]
fn original_page_attempt_comes_from_the_physical_allocator(){
 let(_,heap)=observe(||{let mut probe=Vec::<u8>::with_capacity(73);probe.resize(73,9);std::hint::black_box(&probe);drop(probe)});assert_eq!(heap,(73,73));let fixture:serde_json::Value=serde_json::from_str(include_str!("attempt.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){let mut values=PagedList::<u8,4>::default();let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let copy=values.next_reserve_copy_byte_demand().unwrap();let depth=values.next_reserve_depth_demand().unwrap();let bytes=values.next_allocation_bytes().unwrap();let mut grant=bank.loan(1,copy);grant.maximum_capacity_bytes=bytes;grant.maximum_depth=depth;let mut selected=grant;if row["grant"]=="none"{selected.maximum_capacity_bytes=0}else if row["grant"]=="copyNone"{selected.maximum_copy_bytes=0}else if row["grant"]=="depthNone"{selected.maximum_depth=0}
  let((result,attempts),heap)=observe(||if row["allocator"]=="refuseOnce"{refuse_one_allocation_on_this_thread(||bank.run(grant,1,|effect|{let mut child=effect.reborrow(selected,1).unwrap();RetainedWorkPoll::Complete(values.reserve_one(&mut child))}))}else{(bank.run(grant,1,|effect|{let mut child=effect.reborrow(selected,1).unwrap();RetainedWorkPoll::Complete(values.reserve_one(&mut child))}),0)});let(poll,actual)=result;let turn=match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("unstarted reservation must settle its preflight")};let work=turn.work;let progress=match turn.result{Ok(PagedListReservationOutcome::Denied)=>RetainedCloneProgress::default(),Ok(PagedListReservationOutcome::Ready(p))=>RetainedCloneProgress{copied_items:usize::from(p.progressed),copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,..Default::default()},Err(PagedListReservationFailure::Allocation{error,copied_bytes})=>RetainedCloneProgress{copied_items:usize::from(error.allocated_bytes!=0||copied_bytes!=0),copied_bytes,retained_capacity_bytes:error.allocated_bytes,..Default::default()},Err(PagedListReservationFailure::Work(error))=>panic!("unexpected original Work refusal: {error}")};assert_eq!(work,u128::from(row["work"].as_u64().unwrap()));if work>0{assert_eq!(bank.take_admitted(),Some(true))}else{assert_eq!(bank.take_admitted(),None)}if row["actual"].is_null(){assert!(actual.is_none());assert_eq!(heap,(0,0))}else if row["actual"]=="observed"{assert!(heap.0>0);assert_eq!(actual,Some(heap.0));assert_eq!(progress.retained_capacity_bytes,heap.0)}else{assert_eq!(attempts,1);assert_eq!(actual,Some(0));assert_eq!(heap,(0,0))}bank.post(progress,grant,heap);
  while !values.terminal_is_empty(){let copy=values.next_release_copy_byte_demand().unwrap();let depth=values.next_release_depth_demand().unwrap();let release=values.next_release_allocation_bytes().unwrap();let mut grant=bank.loan(1,copy);grant.maximum_depth=depth;grant.maximum_release_bytes=release;let((poll,actual),heap)=observe(||bank.run(grant,1,|effect|RetainedWorkPoll::Complete(values.release_empty_page(effect))));let turn=match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("synchronous original page release remained pending")};let step=match turn.result.unwrap(){PagedListReleaseOutcome::Ready(step)=>step,PagedListReleaseOutcome::Denied=>panic!("exact original release was denied")};assert_eq!(actual,None);assert_eq!(bank.take_admitted(),Some(true));let progress=RetainedCloneProgress{copied_items:usize::from(step.progressed),copied_bytes:step.placed_bytes,released_bytes:step.released_allocation_bytes,..Default::default()};assert_eq!(heap,(0,progress.released_bytes));bank.post(progress,grant,heap);}
 }
}


/// ⛽️ The capacity quote follows the same real reservation frontier as the one-slot service.
#[test]
fn capacity_work_quote_uses_the_original_selected_frontier(){
 let rows:serde_json::Value=serde_json::from_str(include_str!("capacity-quote.json")).unwrap();let list=PagedList::<u8,4>::default();let selected=list.reserve_one_work_demand().unwrap();
 for row in rows.as_array().unwrap(){let capacity=row["capacity"].as_u64().unwrap()as usize;match row["expected"].as_str().unwrap(){"zero"=>assert_eq!(list.reserve_capacity_one_work_demand(capacity).unwrap(),0),"same-selected"=>assert_eq!(list.reserve_capacity_one_work_demand(capacity).unwrap(),selected),"refused"=>assert!(list.reserve_capacity_one_work_demand(capacity).is_err()),_=>panic!("unknown quoted frontier")}}
}
